28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "address_line1")
44	    private String addressLine1;
45	
46	    @Column(name = "address_line2")
47	    private String addressLine2;
48	
49	    @Column(name = "city")
50	    @NotEmpty
51	    private String city;
52	
53	    @Column(name = "telephone")
54	    @NotEmpty
55	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: a leading '+' followed by 8 to 15 digits")
56	    private String telephone;
57	
58	    @Column(name = "email")
59	    @Email
60	    private String email;
61	
62	    @Column(name = "registration_date", columnDefinition = "DATE")
63	    private LocalDate registrationDate;
64	
65	    @Column(name = "birth_date", columnDefinition = "DATE")
66	    private LocalDate birthDate;
67	
68	    @Column(name = "customer_code")
69	    private String customerCode;
70	
71	    @Column(name = "household_id")
72	    private String householdId;
73	
74	    @Column(name = "namesake_count")
75	    private Integer namesakeCount;
76	
77	    @Column(name = "household_size")
78	    private Integer householdSize;
79	
80	    @Column(name = "postcode")
81	    private String postcode;
82	
83	    @Column(name = "possible_duplicate")
84	    private Boolean possibleDuplicate;
85	
86	    @Column(name = "possible_duplicate_of")
87	    private Integer possibleDuplicateOf;
88	
89	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
90	    private Set<Pet> pets;
91	
92	    public String getAddress() {
93	        return this.address;
94	    }
95	
96	    public void setAddress(String address) {
97	        this.address = address;
98	    }
99	
100	    public String getAddressLine1() {
101	        return this.addressLine1;
102	    }
103	
104	    public void setAddressLine1(String addressLine1) {
105	        this.addressLine1 = addressLine1;
106	    }
107	
108	    public String getAddressLine2() {
109	        return this.addressLine2;
110	    }
111	
112	    public void setAddressLine2(String addressLine2) {
113	        this.addressLine2 = addressLine2;
114	    }
115	
116	    public String getCity() {
117	        return this.city;
118	    }
119	
120	    public void setCity(String city) {
121	        this.city = city;
122	    }
123	
124	    public String getTelephone() {
125	        return this.telephone;
126	    }
127	
128	    public void setTelephone(String telephone) {
129	        this.telephone = telephone;
130	    }
131	
132	    public String getEmail() {
133	        return this.email;
134	    }
135	
136	    /**
137	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
138	     * {@code null} value (email omitted) is preserved as {@code null}.
139	     */
140	    public void setEmail(String email) {
141	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
142	    }
143	
144	    public LocalDate getRegistrationDate() {
145	        return this.registrationDate;
146	    }
147	
148	    public void setRegistrationDate(LocalDate registrationDate) {
149	        this.registrationDate = registrationDate;
150	    }
151	
152	    public LocalDate getBirthDate() {
153	        return this.birthDate;
154	    }
155	
156	    public void setBirthDate(LocalDate birthDate) {
157	        this.birthDate = birthDate;
158	    }
159	
160	    /**
161	     * The owner's age band, derived from {@link #birthDate} measured against the
162	     * {@link #registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64
163	     * inclusive, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
164	     * supplied, so the field is simply absent from the response.
165	     */
166	    @Transient
167	    public String getAgeBand() {
168	        if (this.birthDate == null) {
169	            return null;
170	        }
171	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
172	        int age = java.time.Period.between(this.birthDate, reference).getYears();
173	        if (age < 18) {
174	            return "MINOR";
175	        }
176	        if (age < 65) {
177	            return "ADULT";
178	        }
179	        return "SENIOR";
180	    }
181	
182	    /** National-number length by country code, mirroring the create-time E.164 normalization. */
183	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
184	
185	    /**
186	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
187	     * national digits grouped in threes from the left (e.g. {@code +61412345678 -> +61 412 345 678}).
188	     * The country code is recognised from the known set ({@code +61} with 9 national digits, {@code +1}
189	     * with 10) that the create-time normalization produces. Values that are absent or not in E.164 form
190	     * are returned unchanged, so the raw {@link #telephone} still stands in for a display value.
191	     */
192	    @Transient
193	    public String getTelephoneDisplay() {
194	        if (this.telephone == null || !this.telephone.startsWith("+")) {
195	            return this.telephone;
196	        }
197	        String digits = this.telephone.substring(1);
198	        if (!digits.matches("[0-9]+")) {
199	            return this.telephone;
200	        }
201	        String countryCode = null;
202	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
203	            if (digits.startsWith(entry.getKey())
204	                && digits.length() - entry.getKey().length() == entry.getValue()) {
205	                countryCode = entry.getKey();
206	                break;
207	            }
208	        }
209	        if (countryCode == null) {
210	            return this.telephone;
211	        }
212	        String national = digits.substring(countryCode.length());
213	        StringBuilder grouped = new StringBuilder();
214	        for (int i = 0; i < national.length(); i += 3) {
215	            if (grouped.length() > 0) {
216	                grouped.append(' ');
217	            }
218	            grouped.append(national, i, Math.min(i + 3, national.length()));
219	        }
220	        return "+" + countryCode + " " + grouped;
221	    }
222	
223	    public String getCustomerCode() {
224	        return this.customerCode;
225	    }
226	
227	    public void setCustomerCode(String customerCode) {
228	        this.customerCode = customerCode;
229	    }
230	
231	    /**
232	     * A single Luhn check digit (0-9) computed over the digits contained in the
233	     * {@link #customerCode}. Non-digit characters in the code are ignored; the standard Luhn
234	     * algorithm doubles every second digit from the right (subtracting 9 when the result exceeds
235	     * 9) and the check digit is {@code (10 - (sum % 10)) % 10}. {@code null} until a customer code
236	     * is assigned.
237	     */
238	    @Transient
239	    public Integer getCheckDigit() {
240	        if (this.customerCode == null) {
241	            return null;
242	        }
243	        int sum = 0;
244	        boolean dbl = true;
245	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
246	            char c = this.customerCode.charAt(i);
247	            if (c < '0' || c > '9') {
248	                continue;
249	            }
250	            int d = c - '0';
251	            if (dbl) {
252	                d *= 2;
253	                if (d > 9) {
254	                    d -= 9;
255	                }
256	            }
257	            sum += d;
258	            dbl = !dbl;
259	        }
260	        return (10 - (sum % 10)) % 10;
261	    }
262	
263	    /**
264	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where {@code YY} is
265	     * the last two digits of the {@code registrationDate} year (e.g. {@code NSW-1A2B3C4D-M26}).
266	     * Derived from the owner's own fields; {@code null} until both are assigned.
267	     */
268	    @Transient
269	    public String getMembershipNumber() {
270	        if (this.customerCode == null || this.registrationDate == null) {
271	            return null;
272	        }
273	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
274	    }
275	
276	    /**
277	     * The owner's membership points, derived from the owner's own fields. Points start at 0 and
278	     * accumulate: 2 when an email is present, 1 when the owner has no namesakes ({@code namesakeCount}
279	     * is 0), 2 when the owner belongs to a household of 3 or more members ({@code householdSize} is at
280	     * least 3), and 3 when the owner's tenure — whole days from {@link #registrationDate} to today —
281	     * exceeds 365. Because a newly created owner registers today and so has zero tenure, and joins a
282	     * household of at most itself unless others already share it, a new owner's points reflect only the
283	     * factors captured at creation time.
284	     */
285	    @Transient
286	    public Integer getMembershipPoints() {
287	        int points = 0;
288	        boolean hasEmail = this.email != null && !this.email.isBlank();
289	        if (hasEmail) {
290	            points += 2;
291	        }
292	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
293	        if (noNamesakes) {
294	            points += 1;
295	        }
296	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
297	        if (largeHousehold) {
298	            points += 2;
299	        }
300	        boolean longTenure = this.registrationDate != null
301	            && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
302	        if (longTenure) {
303	            points += 3;
304	        }
305	        return points;
306	    }
307	
308	    /**
309	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
310	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
311	     * points.
312	     */
313	    @Transient
314	    public Integer getMembershipLevel() {
315	        int points = getMembershipPoints();
316	        if (points <= 1) {
317	            return 1;
318	        }
319	        if (points <= 3) {
320	            return 2;
321	        }
322	        if (points <= 5) {
323	            return 3;
324	        }
325	        return 4;
326	    }
327	
328	    /** City -> canonical region for the {@code region} derivation. */
329	    private static final Map<String, String> CITY_REGION = Map.of(
330	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
331	
332	    /** Region -> inclusive 4-digit postcode range {low, high} for the {@code region} derivation. */
333	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
334	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
335	
336	    /** Region -> IANA timezone for the {@code timezone} derivation. */
337	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
338	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
339	
340	    /**
341	     * The region code that forms the {@code REGION} segment of the {@link #customerCode}, derived
342	     * by looking up the region by {@link #postcode} range first (NSW 2000-2099, VIC 3000-3099,
343	     * QLD 4000-4099), and only falling back to the fixed city-to-region table (Sydney->NSW,
344	     * Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no known range. Returns
345	     * {@code UNKNOWN} when neither source resolves a region.
346	     */
347	    @Transient
348	    public String getRegion() {
349	        String region = regionForPostcode(this.postcode);
350	        if (region != null) {
351	            return region;
352	        }
353	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
354	    }
355	
356	    /**
357	     * The owner's locality: the {@code REGION} segment of its {@link #customerCode} (everything
358	     * before the first {@code '-'}). Because the customer code is {@code <REGION>-<HASH8>} with
359	     * {@code REGION} derived from the postcode, the locality now simply reads that region back off
360	     * the identity. Returns {@code UNKNOWN} until a customer code is assigned.
361	     */
362	    @Transient
363	    public String getLocality() {
364	        if (this.customerCode == null) {
365	            return "UNKNOWN";
366	        }
367	        int dash = this.customerCode.indexOf('-');
368	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
369	    }
370	
371	    /**
372	     * The owner's timezone as an IANA name, derived from its {@link #getLocality() locality} (the
373	     * region) via the fixed region-to-timezone table: {@code NSW->Australia/Sydney},
374	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}. Returns {@code null} when
375	     * the locality is not one of those regions.
376	     */
377	    @Transient
378	    public String getTimezone() {
379	        return REGION_TIMEZONE.get(getLocality());
380	    }
381	
382	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
383	    private static String regionForPostcode(String postcode) {
384	        if (postcode == null) {
385	            return null;
386	        }
387	        int value;
388	        try {
389	            value = Integer.parseInt(postcode.trim());
390	        }
391	        catch (NumberFormatException ex) {
392	            return null;
393	        }
394	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
395	            int[] range = entry.getValue();
396	            if (value >= range[0] && value <= range[1]) {
397	                return entry.getKey();
398	            }
399	        }
400	        return null;
401	    }
402	
403	    /**
404	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
405	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
406	     * is the stored E.164 value, the email is the stored lower-cased value (empty when absent) and
407	     * the household segment is the deterministic {@code householdId} derived from the last name and
408	     * postcode (empty only when no household id has been assigned). Two owners are duplicates only
409	     * when their whole identity keys are equal.
410	     */
411	    @Transient
412	    public String getIdentityKey() {
413	        String telephonePart = this.telephone == null ? "" : this.telephone;
414	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
415	        String householdPart = this.householdId == null ? "" : this.householdId;
416	        return telephonePart + "|" + emailPart + "|" + householdPart;
417	    }
418	
419	    public String getHouseholdId() {
420	        return this.householdId;
421	    }
422	
423	    public void setHouseholdId(String householdId) {
424	        this.householdId = householdId;
425	    }
426	
427	    public Integer getNamesakeCount() {
428	        return this.namesakeCount;
429	    }
430	
431	    public void setNamesakeCount(Integer namesakeCount) {
432	        this.namesakeCount = namesakeCount;
433	    }
434	
435	    public Integer getHouseholdSize() {
436	        return this.householdSize;
437	    }
438	
439	    public void setHouseholdSize(Integer householdSize) {
440	        this.householdSize = householdSize;
441	    }
442	
443	    public String getPostcode() {
444	        return this.postcode;
445	    }
446	
447	    public void setPostcode(String postcode) {
448	        this.postcode = postcode;
449	    }
450	
451	    public Boolean getPossibleDuplicate() {
452	        return this.possibleDuplicate;
453	    }
454	
455	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
456	        this.possibleDuplicate = possibleDuplicate;
457	    }
458	
459	    public Integer getPossibleDuplicateOf() {
460	        return this.possibleDuplicateOf;
461	    }
462	
463	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
464	        this.possibleDuplicateOf = possibleDuplicateOf;
465	    }
466	
467	    protected Set<Pet> getPetsInternal() {
468	        if (this.pets == null) {
469	            this.pets = new HashSet<>();
470	        }
471	        return this.pets;
472	    }
473	
474	    protected void setPetsInternal(Set<Pet> pets) {
475	        this.pets = pets;
476	    }
477	
478	    public List<Pet> getPets() {
479	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
480	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
481	        return Collections.unmodifiableList(sortedPets);
482	    }
483	
484	    public void setPets(List<Pet> pets) {
485	        this.pets = new HashSet<>(pets);
486	    }
487	
488	    public void addPet(Pet pet) {
489	        getPetsInternal().add(pet);
490	        pet.setOwner(this);
491	    }
492	
493	    /**
494	     * Return the Pet with the given name, or null if none found for this Owner.
495	     *
496	     * @param name to test
497	     * @return true if pet name is already in use
498	     */
499	    public Pet getPet(String name) {
500	        return getPet(name, false);
501	    }
502	
503	    /**
504	     * Return the Pet with the given name, or null if none found for this Owner.
505	     *
506	     * @param name to test
507	     * @return true if pet name is already in use
508	     */
509	    public Pet getPet(String name, boolean ignoreNew) {
510	        name = name.toLowerCase();
511	        for (Pet pet : getPetsInternal()) {
512	            if (!ignoreNew || !pet.isNew()) {
513	                String compName = pet.getName();
514	                compName = compName.toLowerCase();
515	                if (compName.equals(name)) {
516	                    return pet;
517	                }
518	            }
519	        }
520	        return null;
521	    }
522	
523	    public Pet getPet(Integer petId) {
524	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
525	    }
526	
527	    @Override
528	    public String toString() {
529	        return new ToStringCreator(this)
530	
531	            .append("id", this.getId())
532	            .append("new", this.isNew())
533	            .append("lastName", this.getLastName())
534	            .append("firstName", this.getFirstName())
535	            .append("address", this.address)
536	            .append("city", this.city)
537	            .append("telephone", this.telephone)
538	            .append("email", this.email)
539	            .toString();
540	    }
541	}
