119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
122	        // Prefer the structured address fields when present; the flat 'address' input remains accepted
123	        // for backward compatibility. When structured, the stored/returned address is the composed
124	        // normalized addressLine1 (with a single space and the normalized addressLine2 appended when
125	        // addressLine2 is present); otherwise it is the normalized flat 'address'.
126	        boolean structured = !isBlank(ownerFieldsDto.getAddressLine1());
127	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
128	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
129	        String address;
130	        if (structured) {
131	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
132	        } else {
133	            address = normalizeAddress(ownerFieldsDto.getAddress());
134	        }
135	        List<String> missingFields = new ArrayList<>();
136	        if (isBlank(ownerFieldsDto.getFirstName())) {
137	            missingFields.add("firstName");
138	        }
139	        if (isBlank(ownerFieldsDto.getLastName())) {
140	            missingFields.add("lastName");
141	        }
142	        if (isBlank(address)) {
143	            missingFields.add("address");
144	        }
145	        if (isBlank(ownerFieldsDto.getCity())) {
146	            missingFields.add("city");
147	        }
148	        if (isBlank(ownerFieldsDto.getTelephone())) {
149	            missingFields.add("telephone");
150	        }
151	        if (!missingFields.isEmpty()) {
152	            throw new MissingOwnerFieldsException(missingFields);
153	        }
154	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
155	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
156	        HttpHeaders headers = new HttpHeaders();
157	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
158	        owner.setAddress(address);
159	        owner.setAddressLine1(structured ? addressLine1 : null);
160	        owner.setAddressLine2(structured && !addressLine2.isEmpty() ? addressLine2 : null);
161	        owner.setTelephone(telephone);
162	        validateEmailDomain(owner.getEmail());
163	        validatePostcode(owner.getPostcode(), owner.getRegion());
164	        // The household is keyed deterministically on (lastName, postcode): every owner receives the
165	        // same stable householdId as anyone sharing its normalized last name and postcode, without any
166	        // explicit link. This computed value drives duplicate detection and the household size.
167	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
168	        // A second owner joining an existing household (same computed householdId) is rejected as a
169	        // household duplicate. Declaring 'sharesHousehold' only bypasses this block — it no longer
170	        // creates the link, since the link is now implicit in the computed householdId.
171	        if (!sharesHousehold && isHouseholdInUse(owner)) {
172	            throw new DuplicateIdentityException(owner.getIdentityKey());
173	        }
174	        // Remaining duplicate detection is consolidated into the single derived identity key: a create
175	        // is rejected when the new owner's whole identity key equals an existing owner's.
176	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
177	            throw new DuplicateIdentityException(owner.getIdentityKey());
178	        }
179	        if (isCityAtCapacity(owner.getCity())) {
180	            throw new CityAtCapacityException(owner.getCity());
181	        }
182	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
183	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
184	        }
185	        LocalDate effectiveDate = owner.getRegistrationDate() != null
186	            ? owner.getRegistrationDate() : LocalDate.now();
187	        LocalDate registrationDate = toBusinessDay(effectiveDate);
188	        if (isDailyRegistrationLimitReached(registrationDate)) {
189	            throw new DailyRegistrationLimitException(registrationDate);
190	        }
191	        owner.setRegistrationDate(registrationDate);
192	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(owner)));
193	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
194	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
195	        // A declared household member (one that set 'sharesHousehold' to join an existing household) is
196	        // not a suspected duplicate; otherwise fall back to the soft last-name + postcode match.
197	        Integer possibleDuplicateOf = sharesHousehold ? null : possibleDuplicateOf(owner);
198	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
199	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
200	        this.clinicService.saveOwner(owner);
201	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
202	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
203	            owner.getMembershipNumber());
204	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
205	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
206	        headers.setLocation(UriComponentsBuilder.newInstance()
207	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
208	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
209	    }
