310	    /**
311	     * The set of disposable email domains that owners may not register with. Compared
312	     * case-insensitively against the domain part of the supplied email.
313	     */
314	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
315	        "mailinator.com", "tempmail.com", "guerrillamail.com");
316	
317	    /**
318	     * Rejects an owner whose email domain is on the disposable-domain blocklist
319	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
320	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
321	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
322	     * case-insensitively; the stored email is already lower-cased.
323	     *
324	     * @param email the owner's email (may be {@code null})
325	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
326	     */
327	    private static void validateEmailDomain(String email) {
328	        if (isBlank(email)) {
329	            return;
330	        }
331	        int at = email.lastIndexOf('@');
332	        if (at < 0) {
333	            return;
334	        }
335	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
336	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
337	            throw new DisposableEmailDomainException(email);
338	        }
339	    }
340	
341	    /**
342	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
343	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
344	     */
345	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
346	        "NSW", new int[] {2000, 2099},
347	        "VIC", new int[] {3000, 3099},
348	        "QLD", new int[] {4000, 4099});
349	
350	    /**
351	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
352	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
353	     * present, the value has already passed the 4-digit format check (Bean Validation on the
354	     * request body); this enforces that it falls within the inclusive range for the city's region
355	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
356	     *
357	     * @param postcode the supplied postcode (may be {@code null})
358	     * @param region the owner's locality/region derived from its city
359	     * @throws InvalidPostcodeException if the postcode is out of range for the region
360	     */
361	    private static void validatePostcode(String postcode, String region) {
362	        if (isBlank(postcode)) {
363	            return;
364	        }
365	        int[] range = REGION_POSTCODES.get(region);
366	        if (range == null) {
367	            return;
368	        }
369	        int value;
370	        try {
371	            value = Integer.parseInt(postcode);
372	        }
373	        catch (NumberFormatException e) {
374	            throw new InvalidPostcodeException(postcode);
375	        }
376	        if (value < range[0] || value > range[1]) {
377	            throw new InvalidPostcodeException(postcode);
378	        }
379	    }
380	
381	    /**
382	     * Normalizes a street address into the canonical form stored on and returned for a newly
383	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
384	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
385	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
386	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
387	     * value is what gets persisted, echoed back, and used for every address comparison (household
388	     * duplicate detection and the shared household identifier).
389	     *
390	     * @param rawAddress the address value as supplied by the client
391	     * @return the normalized address (possibly empty, never {@code null})
392	     */
393	    private static String normalizeAddress(String rawAddress) {
394	        if (rawAddress == null) {
395	            return "";
396	        }
397	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
398	        if (collapsed.isEmpty()) {
399	            return "";
400	        }
401	        String[] tokens = collapsed.split(" ");
402	        StringBuilder sb = new StringBuilder(collapsed.length());
403	        for (int i = 0; i < tokens.length; i++) {
404	            String token = tokens[i];
405	            switch (token) {
406	                case "ST" -> token = "STREET";
407	                case "RD" -> token = "ROAD";
408	                case "AVE" -> token = "AVENUE";
409	                default -> { }
410	            }
411	            if (i > 0) {
412	                sb.append(' ');
413	            }
414	            sb.append(token);
415	        }
416	        return sb.toString();
417	    }
418	
419	    /**
420	     * Builds the customer code assigned to a newly created owner. The code is formatted
421	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
422	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
423	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
424	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
425	     * the owner's own region and identity.
426	     *
427	     * @param owner the owner being created, with telephone already normalized and postcode/city set
428	     * @return the customer code to assign
429	     */
430	    private static String customerCodeFor(Owner owner) {
431	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
432	    }
433	
434	    /**
435	     * De-duplicates a freshly computed customer code against the codes already assigned to existing
436	     * owners. When no existing owner carries the given code it is returned unchanged; otherwise the
437	     * smallest suffix {@code -<n>} with {@code n >= 2} that yields a code no existing owner holds is
438	     * appended, guaranteeing distinct owners always receive distinct customer codes.
439	     *
440	     * @param customerCode the customer code computed for the owner being created
441	     * @return the de-duplicated customer code, unique among existing owners
442	     */
443	    private String deduplicateCustomerCode(String customerCode) {
444	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
445	            .map(Owner::getCustomerCode)
446	            .filter(java.util.Objects::nonNull)
447	            .collect(java.util.stream.Collectors.toSet());
448	        if (!existing.contains(customerCode)) {
449	            return customerCode;
450	        }
451	        int n = 2;
452	        while (existing.contains(customerCode + "-" + n)) {
453	            n++;
454	        }
455	        return customerCode + "-" + n;
456	    }
457	
458	    /**
459	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
460	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
461	     * last name.
462	     *
463	     * @param normalizedTelephone the owner's telephone in E.164 form
464	     * @param lastName the owner's last name
465	     * @return the 8-character upper-case hex hash
466	     */
467	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
468	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
469	            + (lastName == null ? "" : lastName);
470	        try {
471	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
472	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
473	            StringBuilder sb = new StringBuilder(digest.length * 2);
474	            for (byte b : digest) {
475	                sb.append(String.format("%02x", b));
476	            }
477	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
478	        }
479	        catch (java.security.NoSuchAlgorithmException e) {
480	            throw new IllegalStateException("SHA-256 not available", e);
481	        }
482	    }
483	
484	    /**
485	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
486	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
487	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
488	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
489	     * the national number must match the country code: {@code +61} requires 9 national digits and
490	     * {@code +1} requires 10.
491	     *
492	     * @param rawTelephone the telephone value as supplied by the client
493	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
494	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
495	     */
496	    private static String normalizeTelephone(String rawTelephone) {
497	        if (rawTelephone == null) {
498	            throw new InvalidTelephoneException(rawTelephone);
499	        }
500	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
501	        String e164;
502	        if (cleaned.startsWith("+")) {
503	            String digits = cleaned.substring(1);
504	            if (!digits.matches("[0-9]+")) {
505	                throw new InvalidTelephoneException(rawTelephone);
506	            }
507	            e164 = "+" + digits;
508	        } else {
509	            if (!cleaned.matches("[0-9]+")) {
510	                throw new InvalidTelephoneException(rawTelephone);
511	            }
512	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
513	            e164 = "+61" + national;
514	        }
515	        int digitCount = e164.length() - 1;
516	        if (digitCount < 8 || digitCount > 15) {
517	            throw new InvalidTelephoneException(rawTelephone);
518	        }
519	        if (e164.startsWith("+61")) {
520	            if (e164.length() - "+61".length() != 9) {
521	                throw new InvalidTelephoneException(rawTelephone);
522	            }
523	        }
524	        else if (e164.startsWith("+1")) {
525	            if (e164.length() - "+1".length() != 10) {
526	                throw new InvalidTelephoneException(rawTelephone);
527	            }
528	        }
529	        return e164;
530	    }
531	
532	    /**
533	     * Determines whether any existing owner already carries the given identity key. The identity key
534	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
535	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
536	     * are equal.
537	     *
538	     * @param identityKey the identity key of the owner being created
539	     * @return {@code true} if another owner already has the same identity key
540	     */
541	    private boolean isIdentityKeyInUse(String identityKey) {
542	        return this.clinicService.findAllOwners().stream()
543	            .map(Owner::getIdentityKey)
544	            .anyMatch(identityKey::equals);
545	    }
546	
547	    /**
548	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
549	     * that shares the same last name (compared case-insensitively, whitespace-collapsed) and the
550	     * same postcode but carries a <em>different</em> telephone. Such a create is not rejected as a
551	     * hard duplicate, but is flagged. An owner with no postcode can never be a soft duplicate. When
552	     * several owners match, the earliest (lowest id) is returned so the result is deterministic.
553	     *
554	     * @param owner the owner being created (telephone already normalized, postcode set)
555	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
556	     */
557	    private Integer possibleDuplicateOf(Owner owner) {
558	        if (isBlank(owner.getPostcode())) {
559	            return null;
560	        }
561	        String normalizedLastName = normalizeIdentity(owner.getLastName());
562	        return this.clinicService.findAllOwners().stream()
563	            .filter(existing -> existing.getId() != null
564	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
565	                && owner.getPostcode().equals(existing.getPostcode())
566	                && !java.util.Objects.equals(owner.getTelephone(), existing.getTelephone()))
567	            .map(Owner::getId)
568	            .min(Integer::compareTo)
569	            .orElse(null);
570	    }
571	
572	    /**
573	     * Counts how many existing owners already share the given first name and last name with the
574	     * owner being created. Both names are compared case-insensitively (after trimming and
575	     * collapsing runs of whitespace). The count reflects the state before the new owner is
576	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
577	     *
578	     * @param firstName the first name of the owner being created
579	     * @param lastName the last name of the owner being created
580	     * @return the number of existing owners sharing the same first and last name
581	     */
582	    private int namesakeCount(String firstName, String lastName) {
583	        String normalizedFirstName = normalizeIdentity(firstName);
584	        String normalizedLastName = normalizeIdentity(lastName);
585	        return (int) this.clinicService.findAllOwners().stream()
586	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
587	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
588	            .count();
589	    }
590	
591	    /**
592	     * Counts how many members the owner being created belongs to in its household, including
593	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
594	     * the new owner is not yet persisted, so its own membership is added to the existing count.
595	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
596	     * household of one.
597	     *
598	     * @param householdId the shared household identifier assigned to the owner being created, or
599	     *                    {@code null} if the owner does not share a household
600	     * @return the number of household members after this create (at least 1)
601	     */
602	    private int householdSizeAfterCreate(String householdId) {
603	        if (householdId == null) {
604	            return 1;
605	        }
606	        long existing = this.clinicService.findAllOwners().stream()
607	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
608	            .count();
609	        return (int) existing + 1;
610	    }
611	
612	    /**
613	     * The maximum number of owners permitted in a single city. Once a city already contains this
614	     * many owners it is considered full and no further owners may be created there.
615	     */
616	    private static final int CITY_CAPACITY = 50;
617	
618	    /**
619	     * Determines whether the given city has already reached its capacity, i.e. already contains
620	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
621	     * collapsing runs of whitespace to a single space and trimming.
622	     *
623	     * @param city the city of the owner being created
624	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
625	     */
626	    private boolean isCityAtCapacity(String city) {
627	        String normalizedCity = normalizeIdentity(city);
628	        long count = this.clinicService.findAllOwners().stream()
629	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
630	            .count();
631	        return count >= CITY_CAPACITY;
632	    }
633	
634	    /**
635	     * The maximum number of owners that may be created on any single day. Once this many owners
636	     * already carry a {@code registrationDate} of the current day, no further owners may be created
637	     * that day.
638	     */
639	    private static final int DAILY_REGISTRATION_LIMIT = 100;
640	
641	    /**
642	     * Determines whether the daily registration limit has already been reached, i.e. whether
643	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
644	     * their {@code registrationDate}.
645	     *
646	     * @param date the current day
647	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
648	     *         registered on the given date
649	     */
650	    /**
651	     * Rolls a registration date forward onto a business day. A date that already falls on a
652	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
653	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
654	     * everything derived from it (the membership number's year segment, the daily create-limit).
655	     *
656	     * @param date the effective registration date (supplied by the client or defaulted to the
657	     *             server's current date)
658	     * @return the same date if it is a weekday, otherwise the following Monday
659	     */
660	    private static LocalDate toBusinessDay(LocalDate date) {
661	        DayOfWeek dayOfWeek = date.getDayOfWeek();
662	        if (dayOfWeek == DayOfWeek.SATURDAY) {
663	            return date.plusDays(2);
664	        }
665	        if (dayOfWeek == DayOfWeek.SUNDAY) {
666	            return date.plusDays(1);
667	        }
668	        return date;
669	    }
670	
671	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
672	        long count = this.clinicService.findAllOwners().stream()
673	            .filter(existing -> date.equals(existing.getRegistrationDate()))
674	            .count();
675	        return count >= DAILY_REGISTRATION_LIMIT;
676	    }
677	
678	    /**
679	     * The number of owners that may be created on a single day before the bulk-signup warning is
680	     * raised. Once <em>more than</em> this many owners already carry the current business day as
681	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
682	     */
683	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
684	
685	    /**
686	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
687	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
688	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
689	     *
690	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
691	     *         registered on today's business day
692	     */
693	    private boolean isBulkSignupWarning() {
694	        LocalDate today = toBusinessDay(LocalDate.now());
695	        long count = this.clinicService.findAllOwners().stream()
696	            .filter(existing -> today.equals(existing.getRegistrationDate()))
697	            .count();
698	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
699	    }
700	
701	    /**
702	     * Determines whether the owner being created joins an existing household, i.e. some other owner
703	     * already carries the same computed {@code householdId} (equivalently, shares its normalized last
704	     * name and postcode). An owner with no postcode is never treated as joining a household, mirroring
705	     * the soft-duplicate rule that an owner with no postcode can never match one.
706	     *
707	     * @param owner the owner being created, with {@code householdId} already computed
708	     * @return {@code true} if another owner already belongs to the same household
709	     */
710	    private boolean isHouseholdInUse(Owner owner) {
711	        if (isBlank(owner.getPostcode())) {
712	            return false;
713	        }
714	        String householdId = owner.getHouseholdId();
715	        return this.clinicService.findAllOwners().stream()
716	            .anyMatch(existing -> existing.getId() != null
717	                && householdId.equals(existing.getHouseholdId()));
718	    }
719	
720	    /**
721	     * Derives the stable household identifier for a given last name and postcode. The value is the
722	     * first 12 upper-case hex characters of the SHA-256 digest of {@code normalizedLastName + '|' +
723	     * postcode}, so it is deterministic across calls and identical for every owner sharing the same
724	     * normalized last name and postcode — they belong to the same household automatically.
725	     *
726	     * @param lastName the last name of the household
727	     * @param postcode the postcode of the household (may be {@code null})
728	     * @return the deterministic household identifier
729	     */
730	    private static String householdIdFor(String lastName, String postcode) {
731	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
732	        try {
733	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
734	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
735	            StringBuilder sb = new StringBuilder(digest.length * 2);
736	            for (byte b : digest) {
737	                sb.append(String.format("%02x", b));
738	            }
739	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
740	        }
741	        catch (java.security.NoSuchAlgorithmException e) {
742	            throw new IllegalStateException("SHA-256 not available", e);
743	        }
744	    }
745	
746	    /**
747	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
748	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
749	     * single space, and the result is lower-cased.
750	     *
751	     * @param value the raw field value
752	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
753	     */
754	    private static String normalizeIdentity(String value) {
755	        if (value == null) {
756	            return "";
757	        }
758	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
759	    }
760	}
